ALTER TABLE "mtu_catalog_items" ADD CONSTRAINT "mtu_catalog_items_mileage_shape" CHECK ("mtu_catalog_items"."requires_mileage" is null or "mtu_catalog_items"."kind" = 'transport');--> statement-breakpoint
